// 机械抽取原两校验体；不在热读中重建 registration 或分配阶段目录。
Status validate_original_motion_phase_author_selection(const WorldBundle& world,MotionExactWorldFactory factory){return status([&]{if(!factory.read||!factory.write)fail("MotionWorldFactoryRequired");auto lease=take(factory.read(world));if(!lease)fail("MotionWorldReadLeaseRequired");take(validate_motion_exact_author_selection(lease->bindings()));});}
Status validate_original_motion_phase_world_sources(const WorldBundle& world,const WorldMoment& at,MotionExactWorldFactory factory,ExactArithmeticBudget b){return status([&]{if(!factory.read)fail("MotionWorldFactoryRequired");auto lease=take(factory.read(world));if(!lease)fail("MotionWorldReadLeaseRequired");take(validate_motion_exact_sources(lease->bindings(),at,b));});}
ExactPhaseRegistration make_motion_exact_phase_registration(MotionExactWorldFactory factory,ExactArithmeticBudget b){const auto max_limbs=b.max_limbs,max_steps=b.max_steps;ExactPhaseRegistration out;out.provider=ExactProviderId::motion;out.profile_id="travel";out.version=4;out.stages={ExactStage::same_moment_hits,ExactStage::immediate_consequences,ExactStage::action_completions,ExactStage::contact_install,ExactStage::patrol_arrival};out.schedule_kind=ExactScheduleKind::exact_due;out.interval_writer=true;out.period_source_owner=false;out.effect_writer_keys={"travel.location","travel.unit_expense","travel.unit_exertion","travel.cargo_handling_service","travel.patrol_checkpoint_arrival"};out.interval_after={ExactProviderId::local_economy};
out.validate_author_selection=[factory](const WorldBundle& world){return validate_original_motion_phase_author_selection(world,factory);};
out.validate_world_sources=[factory,max_limbs,max_steps](const WorldBundle& world,const WorldMoment& at){return validate_original_motion_phase_world_sources(world,at,factory,{max_limbs,max_steps,{}});};
out.predict=[factory,max_limbs,max_steps](const WorldBundle& world,const WorldMoment& from,const WorldMoment& to){ExactArithmeticBudget b{max_limbs,max_steps,{}};return guard<std::vector<ExactEventPrediction>>([&]{if(!factory.read)fail("MotionWorldFactoryRequired");auto lease=take(factory.read(world));if(!lease)fail("MotionWorldReadLeaseRequired");return take(predict_motion_exact_events(lease->bindings(),from,to,b));});};
out.adopt_interval_from=[factory,max_limbs,max_steps](WorldBundle& world,const MomentSpan& span,ExactPhaseWriteContext& context){ExactArithmeticBudget b{max_limbs,max_steps,{}};return status([&]{if(!factory.write)fail("MotionWorldFactoryRequired");auto lease=take(factory.write(world));if(!lease)fail("MotionWorldWriteLeaseRequired");auto w=lease->bindings();take(adopt_motion_exact_interval_from(w,span,context,b));});};
out.provide_interval=[factory,max_limbs,max_steps](WorldBundle& world,const MomentSpan& span,ExactPhaseWriteContext& context){ExactArithmeticBudget b{max_limbs,max_steps,{}};return status([&]{if(!factory.write)fail("MotionWorldFactoryRequired");auto lease=take(factory.write(world));if(!lease)fail("MotionWorldWriteLeaseRequired");auto w=lease->bindings();take(provide_motion_exact_interval(w,span,context,b));});};
out.apply_due=[factory,max_limbs,max_steps](WorldBundle& world,const ExactEventPrediction& prediction,ExactPhaseWriteContext& context){ExactArithmeticBudget b{max_limbs,max_steps,{}};return guard<ExactEventApplied>([&]{if(!factory.write)fail("MotionWorldFactoryRequired");auto lease=take(factory.write(world));if(!lease)fail("MotionWorldWriteLeaseRequired");auto w=lease->bindings();return take(apply_motion_exact_due(w,prediction,context,b));});};
out.validate_applied_source=[factory,max_limbs,max_steps](const WorldBundle& world,const ExactEventApplied& applied){ExactArithmeticBudget b{max_limbs,max_steps,{}};return status([&]{if(!factory.read)fail("MotionWorldFactoryRequired");auto lease=take(factory.read(world));if(!lease)fail("MotionWorldReadLeaseRequired");take(validate_applied(lease->bindings(),applied,b));});};return out;}
